"""Service mesh routing configuration compiler."""
from typing import Dict, Any
from matcher_utils import deep_merge_matchers, normalize_prefix, extract_header_matchers
from route_validator import is_valid_route_pattern, count_route_segments, extract_primary_route, validate_header_matchers

def compile_route_profile(mesh_id: str, base_rules: Dict[str, Any], env_rules: Dict[str, Any]) -> Dict[str, Any]:
    merged = deep_merge_matchers(base_rules, env_rules)
    prefix = normalize_prefix(merged.get("prefix", "/"))
    primary = extract_primary_route(prefix)

    # Extract and validate header matchers
    header_matchers = extract_header_matchers(merged)
    validate_header_matchers(header_matchers)

    return {
        "mesh_id": mesh_id,
        "prefix": prefix,
        "primary": primary,
        "segments": count_route_segments(prefix),
        "rules": merged,
        "headers": header_matchers
    }
